{
  "single_story": {
    "yes": true,
    "note": "All sources cover the same Google support-page change to Gemini model access starting Oct. 9, 2026."
  },
  "the_news": {
    "text": "Starting Oct. 9, 2026, Google will limit free Gemini app users to Flash-Lite only (no Flash or Pro) and remove Pro from AI Plus ($4.99/month) subscribers on a date Google will email them, per an updated Google support page; AI Pro ($19.99/month) is the cheapest plan that keeps all three models.",
    "ids": [
      "F1",
      "F2",
      "F3",
      "F4"
    ]
  },
  "why_it_matters": [
    {
      "text": "Free users lose the model picker's Flash and Pro options, and anyone relying on Pro (coding, studying, large files) on free or AI Plus must pay $19.99/month for AI Pro to keep it, an extra $15/month ($180/year) over AI Plus per Yahoo's math.",
      "ids": [
        "F1",
        "F2",
        "F3",
        "F6"
      ]
    },
    {
      "text": "The change touches a very large user base: Google says Gemini passed 1 billion monthly users in August (Google's own claim as relayed by Yahoo), and PCMag ties it to rising storage and component costs, noting Google has not itself been quoted giving that reason.",
      "ids": [
        "F9",
        "F10"
      ]
    }
  ],
  "facts": [
    {
      "id": "F1",
      "text": "Beginning Oct. 9, Gemini app users without a paid Google AI subscription will lose access to Flash and Pro and be limited to Flash-Lite.",
      "sources": [
        "Yahoo Creators",
        "Engadget",
        "9to5Google",
        "PCMag"
      ],
      "claim_by": null,
      "notes": [
        "Based on an updated Google support page, per 9to5Google, Engadget and PCMag. The support page version I opened still showed all models available to all plans (likely an older/cached version), so I could not verify the new wording directly."
      ]
    },
    {
      "id": "F2",
      "text": "Google AI Plus subscribers will keep Flash-Lite and Flash but lose Pro; they will receive an email explaining when the changes take effect for their account, so their date may differ from Oct. 9.",
      "sources": [
        "9to5Google",
        "Yahoo Creators",
        "PCMag",
        "Engadget"
      ],
      "claim_by": null,
      "notes": [
        "Engadget says AI Plus users will lose Gemini 3.1 Pro but doesn't mention the email."
      ]
    },
    {
      "id": "F3",
      "text": "AI Pro and AI Ultra see no regressions: both keep Flash-Lite, Flash and Pro, and AI Pro will gain the Deep Think option, currently only on the $99.99 and $199.99/month plans.",
      "sources": [
        "9to5Google",
        "Yahoo Creators"
      ],
      "claim_by": null,
      "notes": [
        "Engadget says Ultra subscribers get Deep Think; 9to5Google says Pro is adding it. Yahoo says Pro requires AI Pro or AI Ultra."
      ]
    },
    {
      "id": "F4",
      "text": "Model versions named by 9to5Google and PCMag: free users keep (3.5) Flash-Lite and lose (3.6) Flash and (3.1) Pro.",
      "sources": [
        "9to5Google",
        "PCMag"
      ],
      "claim_by": null,
      "notes": [
        "Yahoo and Engadget use generic names (Flash-Lite, Flash, Pro), with Engadget naming only Gemini 3.1 Pro."
      ]
    },
    {
      "id": "F5",
      "text": "Google is adding low, medium and high effort levels for each available model in the Gemini app; higher levels give more thorough answers but use more of the user's limit.",
      "sources": [
        "9to5Google",
        "PCMag",
        "Engadget"
      ],
      "claim_by": null,
      "notes": [
        "9to5Google says the app 'looks to be adding' these levels in October; PCMag says users will 'soon' be able to choose."
      ]
    },
    {
      "id": "F6",
      "text": "Google currently lists AI Plus at $4.99/month, AI Pro at $19.99/month and AI Ultra from $99.99/month in the U.S.; a Plus subscriber who wants to keep Pro would pay another $15 a month, or $180 a year.",
      "sources": [
        "Yahoo Creators",
        "PCMag",
        "9to5Google"
      ],
      "claim_by": null,
      "notes": [
        "The $15 and $180 figures are Yahoo's arithmetic from list prices."
      ]
    },
    {
      "id": "F7",
      "text": "Eligible U.S. college students can get one year of AI Pro free (valued at $19.99/month), redeemable through Dec. 31, 2026; a valid payment method is required and it charges $19.99/month after the free year unless canceled.",
      "sources": [
        "Yahoo Creators"
      ],
      "claim_by": null,
      "notes": [
        "PCMag also says students remain eligible for a free year of AI Pro but gives no details."
      ]
    },
    {
      "id": "F8",
      "text": "AI Ultra subscribers will also get access to Gemini 4 Argon once it launches generally; it is currently available only to members of Google's Fairwind program for governments and trusted partners.",
      "sources": [
        "Engadget",
        "9to5Google"
      ],
      "claim_by": null,
      "notes": [
        "9to5Google says it is unclear whether Argon will be a Pro model or a new tier above it."
      ]
    },
    {
      "id": "F9",
      "text": "Google says Gemini passed 1 billion monthly users in August.",
      "sources": [
        "Yahoo Creators"
      ],
      "claim_by": "Google",
      "notes": [
        "Company figure relayed by Yahoo; not independently confirmed in the sources I opened."
      ]
    },
    {
      "id": "F10",
      "text": "PCMag says this is the second time Google has overhauled its AI plans this year and that the changes come as storage and component costs keep rising, potentially affecting Google's AI infrastructure spending.",
      "sources": [
        "PCMag"
      ],
      "claim_by": "PCMag",
      "notes": [
        "PCMag's own hedged inference; Google is not quoted giving a reason."
      ]
    },
    {
      "id": "F11",
      "text": "PCMag reports AI Plus and AI Pro offer 2x and 5x Gemini usage limits versus the free plan, and that Google does not explain how limits are calculated.",
      "sources": [
        "PCMag"
      ],
      "claim_by": null,
      "notes": [
        "The Google support page I opened lists AI Plus at 2x and AI Pro at 4x higher than standard limits, and AI Ultra at 5x or 20x higher than AI Pro. That conflicts with PCMag's 5x for Pro."
      ]
    }
  ],
  "background": [
    {
      "id": "B1",
      "text": "The model-access limits follow a compute-based usage limit change Google made to the Gemini app in May.",
      "sources": [
        "9to5Google"
      ],
      "claim_by": null,
      "notes": [
        "Google's support page says limits are compute-based and factor in prompt complexity, models and features used, and chat length; limits refresh every 5 hours until a weekly limit is hit."
      ]
    }
  ],
